import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { toggleAutoPostHandler } from "../handlers/toggleAutoPostHandler";
import type { ApiError } from "../runtime/client";
import type { SocialPlatform } from "../types/SocialPlatform";
import type { ToggleAutoPostRequest } from "../types/ToggleAutoPostRequest";

type Data = Awaited<ReturnType<typeof toggleAutoPostHandler>>;
type Vars = { platform: SocialPlatform; req: ToggleAutoPostRequest };

export function useToggleAutoPost(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => toggleAutoPostHandler(vars.platform, vars.req),
    ...options,
  });
}
